const $=s=>document.querySelector(s);let category='all';let saved=JSON.parse(localStorage.getItem('pati-favorites')||'[]');let pending=JSON.parse(localStorage.getItem('pati-pending')||'[]');const photos=['photo-1633722715463-d30f4f325e24','photo-1551717743-49959800b1f6','photo-1573865526739-10659fec78a5','photo-1587300003388-59208cc962cb'];const listings=[{id:1,name:'Yeni oyun arkadaşınız: Leo',breed:'Golden Retriever',city:'İstanbul',age:'3 aylık',sex:'Erkek',animal:'dog',category:'adoption',tag:'Yuva arıyor'},{id:2,name:'Maya bir dost arıyor',breed:'Border Collie',city:'Ankara',age:'2 yaşında',sex:'Dişi',animal:'dog',category:'mate',tag:'Eş bulma'},{id:3,name:'Minik Luna ile tanışın',breed:'British Shorthair',city:'İzmir',age:'5 aylık',sex:'Dişi',animal:'cat',category:'adoption',tag:'Yuva arıyor'},{id:4,name:'Bir avuç mutluluk: Teddy',breed:'Pomeranian',city:'İstanbul',age:'4 aylık',sex:'Erkek',animal:'dog',category:'adoption',tag:'Yuva arıyor'},{id:5,name:'Pamuk için yardımınızı bekliyoruz',breed:'Golden Retriever',city:'Ankara',age:'3 yaşında',sex:'Dişi',animal:'dog',category:'lost',tag:'Kayıp dost'},{id:6,name:'Yeni yuvalara mama paylaşımı',breed:'Mama & aksesuar',city:'İstanbul',age:'Paylaşım',sex:'Mama',animal:'dog',category:'accessory',tag:'Paylaşım'}];const img=i=>`https://images.unsplash.com/${photos[(i-1)%4]}?auto=format&fit=crop&w=650&q=80`;function render(){const filtered=listings.filter(x=>(category==='all'||x.category===category)&&($('#animal').value==='all'||x.animal===$('#animal').value)&&($('#breed').value==='all'||x.breed===$('#breed').value)&&($('#city').value==='all'||x.city===$('#city').value));$('#cards').innerHTML=filtered.length?filtered.map(x=>`<article class="card"><div class="photo"><img loading="lazy" src="${img(x.id)}" alt="${x.breed} örnek fotoğrafı"><span class="badge ${x.category==='mate'?'gold':''}">${x.tag}</span><button class="heart ${saved.includes(x.id)?'saved':''}" aria-label="${saved.includes(x.id)?'Favorilerden çıkar':'Favorilere ekle'}" data-save="${x.id}">${saved.includes(x.id)?'♥':'♡'}</button></div><div class="card-body"><div class="meta"><span>${x.breed}</span><span>✓ Örnek ilan</span></div><h3>${x.name}</h3><div class="chips"><span>${x.age}</span><span>${x.sex}</span></div><div class="card-foot"><span>⌖ ${x.city}</span><button class="textlink" style="border:0;background:none;font-size:10px;padding:0" data-detail="${x.id}">Tanışalım ↗</button></div></div></article>`).join(''):'<div class="empty">Bu filtrelere uygun bir örnek ilan bulunamadı. Filtreleri değiştirerek tekrar deneyin.</div>'; }render();$('#search').addEventListener('submit',e=>{e.preventDefault();render();$('#listings').scrollIntoView({behavior:'smooth'})});document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t===b));render()});$('#all-listings').onclick=()=>{category='all';['animal','breed','city'].forEach(id=>$('#'+id).value='all');document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.category==='all'));render()};const dialog=$('#modal');function show(html){$('#modal-content').innerHTML=html;dialog.showModal()}$('.close').onclick=()=>dialog.close();dialog.onclick=e=>{if(e.target===dialog)dialog.close()};function toast(msg){$('.toast')?.remove();let t=document.createElement('div');t.className='toast';t.setAttribute('role','status');t.textContent=msg;document.body.append(t);setTimeout(()=>t.remove(),4000)}function form(type){return `<h2>${type==='listing'?'Yeni ilan oluştur':'Çiftlik ziyareti & rezervasyon'}</h2><p>Demo formu: Talebiniz bu tarayıcıda saklanır. Gerçek bir başvuru gönderilmez.</p><form id="request-form"><label>Adınız<input name="name" required maxlength="80" placeholder="Ad Soyad"></label><label>E-posta<input name="email" type="email" required placeholder="ornek@eposta.com"></label>${type==='listing'?'<label>İlan kategorisi<select name="category"><option>Ücretsiz sahiplendirme</option><option>Eş bulma</option><option>Kayıp ilanı</option><option>Mama & aksesuar</option></select></label><label>İlan başlığı<input name="title" required maxlength="100"></label><label>Fotoğraf<input type="file" accept="image/*" name="photo"></label>':'<label>İlgilendiğiniz dost / ziyaret tarihi<input name="title" required placeholder="Örn. Golden Retriever / 15 Ekim"></label>'}<label>Mesajınız<textarea name="message" required rows="3" maxlength="2000"></textarea></label><button class="btn" type="submit">${type==='listing'?'Onay için kaydet':'Talebi kaydet'} →</button></form>`}const actions={credits:()=>show('<h2>Size uygun kredi paketi</h2><p>İlan oluşturma: 5 kredi · Vitrinde öne çıkarma: 10 kredi.<br>Örnek paketlerdir. Ödeme sağlayıcısı henüz bağlı değildir; tahsilat yapılmaz.</p><div class="packages">'+[[20,99],[50,199],[100,349]].map(([n,p])=>`<div class="package"><b>${n}</b><small>kredi</small><span>₺${p}</span><button class="btn" data-package="${n}">Paketi seç</button></div>`).join('')+'</div>'),listing:()=>{show(form('listing'));bindForm('listing')},farm:()=>show('<h2>Çiftliğimizi keşfedin</h2><p>Bu bölümün gerçek çiftlik fotoğrafları, hijyen politikası ve üretim standartlarıyla doldurulması planlanır. Görseller temsili kullanılmıştır.</p><div class="dashboard"><div>Yaşam alanları<b>Galeri</b></div><div>Damızlık kayıtları<b>Şecere</b></div><div>Ziyaret planlama<b>Randevu</b></div></div><p>Şecere görünümü; ebeveyn bilgileri, kayıt numarası ve doğrulanmış belgeleri içerecek şekilde tasarlanır. Gerçek belgeler henüz eklenmedi.</p><button class="btn" data-action="reservation">Ziyaret / rezervasyon talebi →</button>'),reservation:()=>{show(form('reservation'));bindForm('reservation')},profile:()=>show(`<h2>Pati hesabım <span class="demo-tag">DEMO</span></h2><div class="dashboard"><div>Kredi bakiyesi<b>0</b></div><div>Favorilerim<b>${saved.length}</b></div><div>Bekleyen ilanlarım<b>${pending.filter(x=>x.type==='listing').length}</b></div></div><p>Üyelik, mesajlaşma ve ödeme bağlantıları canlı sistem kurulumunda etkinleştirilecek. Kaydedilen demo formları yalnızca bu tarayıcıda tutulur.</p><button class="btn" data-action="credits">Kredi paketleri</button>`),admin:()=>show(`<h2>Yönetim paneli <span class="demo-tag">DEMO</span></h2><div class="dashboard"><div>Günlük kredi cirosu<b>₺0</b></div><div>Bekleyen ilanlar<b>${pending.filter(x=>x.type==='listing').length}</b></div><div>Rezervasyonlar<b>${pending.filter(x=>x.type==='reservation').length}</b></div></div><p>Bu ekran yalnızca yerel demo kayıtlarını gösterir. Gerçek yönetim paneli, yetkilendirme ve sunucu tarafı onay akışı gerektirir.</p><div id="pending-list"></div>`),breeds:()=>show('<h2>Yaşamınıza uyum sağlayan dost</h2><label>Irk seçin<select id="breed-guide"><option>Golden Retriever</option><option>Border Collie</option><option>British Shorthair</option><option>Pomeranian</option></select></label><p id="breed-info"></p>'),library:()=>show('<h2>Pati rehberi</h2><p>Karakter ve bakım ihtiyaçlarını tanıyın, dostunuzla birlikte öğrenin.</p><div class="tabs"><button class="btn" data-action="breeds">Irk rehberi</button><button class="btn" data-action="vaccine">Aşı rehberi</button><button class="btn" data-action="training">Eğitim</button></div>'),vaccine:()=>show('<h2>Aşı rehberi</h2><p>Dostunuzun türü ve yaşam evresine göre veteriner görüşmesinde ele alınabilecek başlıkları keşfedin. Kesin aşı takvimi veteriner hekiminiz tarafından belirlenmelidir.</p><label>Dostunuz<select id="v-species"><option>Köpek</option><option>Kedi</option></select></label><label>Yaşam evresi<select id="v-age"><option>Yavru</option><option>Yetişkin</option><option>İleri yaş</option></select></label><div id="v-output"></div>'),training:()=>show('<h2>Birlikte öğrenin, bağınızı güçlendirin.</h2><p>Kısa, düzenli çalışmalarla başlayın. Sakin bir ortamda istenen davranışı ödüllendirin; aynı kelime ve işaretleri kullanın.</p><p><b>İlk adım:</b> İsmini söylediğinizde size baktığı an ödüllendirin. Dikkati dağıldığında ara verin; eğitimi bir oyun gibi sürdürün.</p><p><b>Bir sonraki adım:</b> Otur, bekle ve geri gel çalışmalarını önce sakin bir yerde, sonra farklı ortamlarda pekiştirin. Zorlu davranışlarda ödül odaklı çalışan nitelikli bir eğitmenden destek alın.</p>'),contact:()=>{show(form('reservation'));bindForm('reservation')},privacy:()=>show('<h2>Demo gizlilik bilgisi</h2><p>Favoriler ve form kayıtları cihazınızın yerel tarayıcı depolamasında tutulur. Bu demoda kayıtlar çiftliğe gönderilmez. Gerçek hizmet yayına alınırken veri sorumlusu bilgileri ve KVKK aydınlatma metni tamamlanmalıdır.</p><button class="btn" id="clear-data">Yerel demo verilerini temizle</button>'),terms:()=>show('<h2>Demo kullanım koşulları</h2><p>Bu site tasarım ve kullanıcı akışlarının incelenmesi için hazırlanmıştır. İlanlar, fiyatlar, fotoğraflar ve çiftlik bilgileri örnektir. Gerçek ödeme, üyelik ve ilan yayını etkin değildir.</p>')};function bindForm(type){$('#request-form').onsubmit=e=>{e.preventDefault();let fd=new FormData(e.target);pending.push({type,name:fd.get('name'),email:fd.get('email'),title:fd.get('title'),message:fd.get('message')});localStorage.setItem('pati-pending',JSON.stringify(pending));dialog.close();toast('Demo talebiniz bu tarayıcıya kaydedildi.')}}const breedTexts={'Golden Retriever':'İnsanlarla yakın ilişki kurmayı seven, düzenli hareket ve tüy bakımı isteyen büyük bir köpektir.','Border Collie':'Zihinsel etkinlik ve hareket ihtiyacı yüksek bir köpektir. Günlük eğitim ve oyun için zaman ayırmak gerekir.','British Shorthair':'Genellikle sakin karakteriyle tanınır. Düzenli oyun, tüy bakımı ve kilo takibi önemlidir.','Pomeranian':'Küçük boyutlu, hareketli bir köpektir. Yoğun tüyleri düzenli tarama gerektirir.'};document.addEventListener('click',e=>{const b=e.target.closest('[data-action],[data-save],[data-detail],[data-package],#clear-data');if(!b)return;e.preventDefault();if(b.dataset.action){actions[b.dataset.action]?.();if(b.dataset.action==='breeds'){const update=()=>$('#breed-info').textContent=breedTexts[$('#breed-guide').value]+' Her hayvanın karakteri ve ihtiyaçları bireyseldir.';$('#breed-guide').onchange=update;update()}if(b.dataset.action==='vaccine'){const update=()=>{$('#v-output').innerHTML=`<p><b>${$('#v-species').value} · ${$('#v-age').value}</b><br>${$('#v-age').value==='Yavru'?'İlk muayene, önceki aşı kayıtları ve temel aşı serisinin planlanması.':'Önceki aşı kayıtlarının değerlendirilmesi ve tekrar dozlarının bireysel risklere göre planlanması.'}<br>Veteriner görüşmesine mevcut sağlık ve aşı kayıtlarını götürün.</p>`};$('#v-species').onchange=update;$('#v-age').onchange=update;update()}if(b.dataset.action==='admin'){pending.forEach(x=>{let p=document.createElement('p');p.textContent=`${x.type==='listing'?'İlan':'Rezervasyon'} · ${x.title} · ${x.name} · Onay bekliyor`;$('#pending-list').append(p)})}}if(b.dataset.save){let id=+b.dataset.save;saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];localStorage.setItem('pati-favorites',JSON.stringify(saved));render()}if(b.dataset.detail){const x=listings.find(x=>x.id==b.dataset.detail);show(`<img src="${img(x.id)}" alt="${x.breed}" style="width:100%;height:240px;object-fit:cover;border-radius:10px;margin-top:20px"><h2>${x.name}</h2><p>${x.breed} · ${x.age} · ${x.sex} · ${x.city}</p><p>Bu örnek ilan, ilan detay ekranını tanıtmak için hazırlanmıştır. Gerçek bir sahiplendirme ilanı değildir.</p><button class="btn" data-action="reservation">Talep formunu incele →</button>`)}if(b.dataset.package)toast(`${b.dataset.package} kredilik paket seçildi. Ödeme entegrasyonu henüz etkin değil.`);if(b.id==='clear-data'){localStorage.removeItem('pati-pending');localStorage.removeItem('pati-favorites');pending=[];saved=[];render();dialog.close();toast('Yerel demo verileri temizlendi.')}});
